/**
 * Demo content for the Hercules workspace.
 *
 * SERVER ONLY in practice - this module is loaded by `store.ts`, which owns the
 * on-disk data file. It performs no I/O itself, so it is safe to unit test.
 *
 * The demo projects are generated by the real generator and then given
 * hand-written names, metrics and conversation history, so what a visitor sees
 * in a seeded project is exactly what the builder produces live.
 */

import {
  applyFollowUp,
  generateSpec,
  initialReply,
  planBuildSteps,
} from "./generator";
import type {
  AppSpec,
  BuildStep,
  Member,
  Message,
  Project,
  ProjectKind,
  ProjectMetrics,
  ProjectStatus,
  User,
  Version,
} from "./types";
import { slugify } from "./utils";

/** Salted password hash for a user who signed up through the demo. */
export interface Credential {
  userId: string;
  salt: string;
  hash: string;
}

/** Everything the store keeps on disk. */
export interface StoreData {
  /** Schema version, so a future migration can detect old files. */
  schema: number;
  users: User[];
  credentials: Credential[];
  projects: Project[];
  messages: Message[];
  versions: Version[];
}

export const SCHEMA_VERSION = 1;

export const DEMO_USER_ID = "usr_alex_rivera";
export const DEMO_USER_EMAIL = "alex@northwind.co";

/* ------------------------------------------------------------------ */
/* Time helpers - seed data is anchored to "now" so it always reads    */
/* as a live workspace.                                                */
/* ------------------------------------------------------------------ */

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

function ago(ms: number): string {
  return new Date(Date.now() - ms).toISOString();
}

