/* ------------------------------------------------------------------ */
/* Project assembly                                                    */
/* ------------------------------------------------------------------ */

interface SeedProjectInput {
  id: string;
  name: string;
  prompt: string;
  kind: ProjectKind;
  status: ProjectStatus;
  domain: string | null;
  version: number;
  createdAgo: number;
  updatedAgo: number;
  metrics: ProjectMetrics;
  members: Member[];
  /** Follow-up chat turns applied after the first build, oldest first. */
  followUps: string[];
}

interface SeedProjectOutput {
  project: Project;
  messages: Message[];
  versions: Version[];
}

function doneSteps(steps: BuildStep[]): BuildStep[] {
  return steps.map((step) => ({ ...step, status: "done" as const }));
}

function buildSeedProject(input: SeedProjectInput, ownerId: string): SeedProjectOutput {
  const baseSpec = generateSpec(input.prompt);
  let spec: AppSpec = { ...baseSpec, title: input.name };
  spec.summary = baseSpec.summary.replace(baseSpec.title, input.name);

  const messages: Message[] = [];
  const versions: Version[] = [];

  // Turn 1: the original prompt and the first build.
  const span = input.createdAgo - input.updatedAgo;
  const turnGap = input.followUps.length > 0 ? span / (input.followUps.length + 1) : span;

  messages.push({
    id: `msg_${input.id}_1`,
    projectId: input.id,
    role: "user",
    content: input.prompt,
    createdAt: ago(input.createdAgo),
  });
  messages.push({
    id: `msg_${input.id}_2`,
    projectId: input.id,
    role: "assistant",
    content: initialReply(spec),
    createdAt: ago(input.createdAgo - 42_000),
    steps: doneSteps(planBuildSteps(input.prompt, spec)),
  });
  versions.push({
    id: `ver_${input.id}_1`,
    projectId: input.id,
    version: 1,
    label: "Initial build",
    createdAt: ago(input.createdAgo - 42_000),
    published: input.status === "live",
  });

  // Follow-up turns, each applied through the real follow-up engine.
  input.followUps.forEach((content, index) => {
    const at = input.createdAgo - turnGap * (index + 1);
    const result = applyFollowUp(spec, content);
    spec = result.spec;
    messages.push({
      id: `msg_${input.id}_${index * 2 + 3}`,
      projectId: input.id,
      role: "user",
      content,
      createdAt: ago(at),
    });
    messages.push({
      id: `msg_${input.id}_${index * 2 + 4}`,
      projectId: input.id,
      role: "assistant",
      content: result.reply,
      createdAt: ago(at - 38_000),
      steps: doneSteps(result.steps),
    });
    versions.push({
      id: `ver_${input.id}_${index + 2}`,
      projectId: input.id,
      version: index + 2,
      label: content.length > 48 ? `${content.slice(0, 45).trim()}...` : content,
      createdAt: ago(at - 38_000),
      published: input.status === "live",
    });
  });

  // Top the version history up to the project's stated version number.
  const polishLabels = [
    "Tightened dashboard tiles",
    "Faster list loading",
    "Copy and layout polish",
    "Added export to CSV",
  ];
  let v = versions.length;
  while (v < input.version) {
    const label = polishLabels[(v - 1) % polishLabels.length] ?? "Maintenance update";
    versions.push({
      id: `ver_${input.id}_${v + 1}`,
      projectId: input.id,
      version: v + 1,
      label,
      createdAt: ago(input.updatedAgo + (input.version - v) * HOUR),
      published: input.status === "live",
    });
    v += 1;
  }

  const project: Project = {
    id: input.id,
    ownerId,
    name: input.name,
    slug: slugify(input.name),
    prompt: input.prompt,
    kind: input.kind,
    status: input.status,
    domain: input.domain,
    version: Math.max(input.version, versions.length),
    createdAt: ago(input.createdAgo),
    updatedAt: ago(input.updatedAgo),
    spec,
    members: input.members,
    metrics: input.metrics,
  };

  return { project, messages, versions };
}

