/* ------------------------------------------------------------------ */
/* Public seeding API                                                  */
/* ------------------------------------------------------------------ */

/** The complete starting state of a fresh install. */
export function createSeedData(): StoreData {
  const user = demoUser();
  const projects: Project[] = [];
  const messages: Message[] = [];
  const versions: Version[] = [];

  for (const input of DEMO_PROJECTS) {
    const built = buildSeedProject(input, user.id);
    projects.push(built.project);
    messages.push(...built.messages);
    versions.push(...built.versions);
  }

  return {
    schema: SCHEMA_VERSION,
    users: [user],
    credentials: [],
    projects,
    messages,
    versions,
  };
}

/**
 * A starter workspace for someone who has just signed up: one draft project so
 * the builder is never an empty screen.
 */
export function seedWorkspace(user: User): {
  projects: Project[];
  messages: Message[];
  versions: Version[];
} {
  const suffix = user.id.replace(/[^a-z0-9]/gi, "").slice(-8) || "new";
  const company = user.company?.trim() || "your team";
  const prompt = `Build an operations dashboard for ${company} that shows work in progress, revenue and the follow-ups my team owes customers.`;
  const built = buildSeedProject(
    {
      id: `prj_welcome_${suffix}`,
      name: `${user.company?.trim() || user.name.split(" ")[0] || "First"} Dashboard`,
      prompt,
      kind: "internal",
      status: "draft",
      domain: null,
      version: 1,
      createdAgo: 4 * MINUTE,
      updatedAgo: 3 * MINUTE,
      metrics: { activeUsers: 1, requests30d: 0, uptime: 100, storageMb: 4 },
      members: [{ id: `mem_${suffix}`, name: user.name, email: user.email, role: "owner" }],
      followUps: [],
    },
    user.id
  );
  return { projects: [built.project], messages: built.messages, versions: built.versions };
}
